const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0], K = data[1], C = data[2];
const A = data.slice(3, 3 + N);

let total = 0;
for (let i = 0; i < N; i++) total += A[i];

if (C === 1) {
  const sorted = A.slice().sort((a, b) => a - b);
  let sumK = 0;
  for (let i = 0; i < K; i++) sumK += sorted[i];
  console.log(total - sumK);
} else {
  const prefix = new Int32Array(N + 1);
  for (let i = 1; i <= N; i++) prefix[i] = prefix[i - 1] + A[i - 1];

  const INF = 1000000000;
  const M = C + 1;
  const rowLen = K + 1;
  const buf = new Int32Array(M * rowLen);
  buf[0] = 0;

  for (let i = 1; i <= N; i++) {
    const curBase = (i % M) * rowLen;
    const prevBase = ((i - 1) % M) * rowLen;
    const maxJ = Math.min(K, Math.floor(i / C));
    const prevMax = Math.min(K, Math.floor((i - 1) / C));
    const cover = i >= C;
    let oldBase = 0;
    let interval = 0;

    if (cover) {
      oldBase = ((i - C) % M) * rowLen;
      interval = prefix[i] - prefix[i - C];
    }

    for (let j = 0; j <= maxJ; j++) {
      let val = (j <= prevMax) ? buf[prevBase + j] : INF;

      if (cover && j > 0) {
        const oldVal = buf[oldBase + j - 1];
        if (oldVal < INF) {
          const cand = oldVal + interval;
          if (cand < val) val = cand;
        }
      }

      buf[curBase + j] = val;
    }
  }

  const minCovered = buf[(N % M) * rowLen + K];
  console.log(total - minCovered);
}
